  function readStoredLanguage() {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (LANGUAGES.some(({ code }) => code === stored)) return stored;
    } catch { /* ignore */ }
    const browser = String(navigator.language || "").slice(0, 2).toLowerCase();
    return LANGUAGES.some(({ code }) => code === browser) ? browser : DEFAULT_LANGUAGE;
  }

  let currentLanguage = readStoredLanguage();

  function interpolate(value, variables = {}) {
    return String(value ?? "").replace(/\{([a-zA-Z0-9_]+)\}/g, (_, key) => String(variables[key] ?? ""));
  }

  function t(key, variables) {
    return interpolate(TRANSLATIONS[currentLanguage]?.[key] ?? es[key] ?? key, variables);
  }

  function apply(root = document) {
    document.documentElement.lang = currentLanguage;
    document.title = t("meta.title");
    for (const [mode, selector, key, attribute] of BINDINGS) {
      const nodes = mode === "attr-all" ? [...root.querySelectorAll(selector)] : [root.querySelector(selector)].filter(Boolean);
      for (const node of nodes) {
        if (mode === "html") node.innerHTML = t(key);
        else if (mode === "text") node.textContent = t(key);
        else node.setAttribute(attribute, t(key));
      }
    }
    const language = LANGUAGES.find(({ code }) => code === currentLanguage);
    const current = document.querySelector("#current-language");
    if (current) current.textContent = language?.short || currentLanguage.toUpperCase();
    document.querySelectorAll("[data-language]").forEach((button) => {
      const selected = button.dataset.language === currentLanguage;
      button.classList.toggle("active", selected);
      button.setAttribute("aria-checked", String(selected));
    });
    const languageButton = document.querySelector("#language-button");
    if (languageButton) languageButton.setAttribute("aria-label", `${t("header.language")}: ${language?.label || currentLanguage}`);
  }

  function setLanguage(language) {
    if (!LANGUAGES.some(({ code }) => code === language) || language === currentLanguage) return;
    currentLanguage = language;
    try { localStorage.setItem(STORAGE_KEY, language); } catch { /* ignore */ }
    apply();
    document.dispatchEvent(new CustomEvent("chessprep:languagechange", { detail: { language } }));
  }

  function getLocale() {
    return LANGUAGES.find(({ code }) => code === currentLanguage)?.locale || "es-ES";
  }

  function getLanguage() { return currentLanguage; }

  global.ChessPrepI18n = { apply, getLanguage, getLocale, languages: LANGUAGES, setLanguage, t };
